// --- 6. Extract() - Field Value Extraction ---
// P010: Must handle all fields defined in Fields()
func (p *ClaudeCodePlugin) Extract(req sdk.ExtractRequest, evt sdk.EventReader) error {
	var event ClaudeCodeEvent
	decoder := gob.NewDecoder(evt.Reader())
	if err := decoder.Decode(&event); err != nil {
		return fmt.Errorf("failed to decode event: %w", err)
	}

	switch req.Field() {
	// Common fields (fixed)
	case "claude_code.log_path":
		req.SetValue(event.LogPath)
	case "claude_code.raw":
		req.SetValue(event.Raw)
	case "claude_code.headers":
		// P012: Header keys must be lowercase
		headerName := strings.ToLower(req.ArgKey())
		if event.Headers != nil {
			if value, ok := event.Headers[headerName]; ok {
				req.SetValue(value)
			}
		}

	// ${DOMAIN_FIELDS_EXTRACT} (§10.2 claude_code.*)
	case "claude_code.schema_version":
		req.SetValue(event.SchemaVersion)
	case "claude_code.received_at":
		req.SetValue(event.ReceivedAt)
	case "claude_code.logger_version":
		req.SetValue(event.LoggerVersion)
	case "claude_code.host":
		req.SetValue(event.Host)
	case "claude_code.user":
		req.SetValue(event.User)
	case "claude_code.session_id":
		req.SetValue(event.SessionID)
	case "claude_code.transcript_path":
		req.SetValue(event.TranscriptPath)
	case "claude_code.cwd":
		req.SetValue(event.Cwd)
	case "claude_code.permission_mode":
		req.SetValue(event.PermissionMode)
	case "claude_code.event_name":
		req.SetValue(event.EventName)
	case "claude_code.source":
		req.SetValue(event.Source)
	case "claude_code.tool_name":
		req.SetValue(event.ToolName)
	case "claude_code.tool_use_id":
		req.SetValue(event.ToolUseID)
	case "claude_code.command":
		req.SetValue(event.Command)
	case "claude_code.command_hash":
		req.SetValue(event.CommandHash)
	case "claude_code.file_path":
		req.SetValue(event.FilePath)
	case "claude_code.file_event":
		req.SetValue(event.FileEvent)
	case "claude_code.url":
		req.SetValue(event.URL)
	case "claude_code.domain":
		req.SetValue(event.Domain)
	case "claude_code.mcp_server_name":
		req.SetValue(event.MCPServerName)
	case "claude_code.mcp_tool_name":
		req.SetValue(event.MCPToolName)
	case "claude_code.mcp_scope":
		req.SetValue(event.MCPScope)
	case "claude_code.permission_destination":
		req.SetValue(event.PermissionDestination)
	case "claude_code.permission_behavior":
		req.SetValue(event.PermissionBehavior)
	case "claude_code.risk_type":
		req.SetValue(event.RiskType)
	case "claude_code.risk_score":
		req.SetValue(event.RiskScore)
	case "claude_code.severity":
		req.SetValue(event.Severity)
	case "claude_code.evidence":
		req.SetValue(event.Evidence)
	case "claude_code.redaction_status":
		req.SetValue(event.RedactionStatus)
	case "claude_code.raw_event_sha256":
		req.SetValue(event.RawEventSHA256)
	case "claude_code.event_size_bytes":
		req.SetValue(event.EventSizeBytes)
	case "claude_code.duration_ms":
		req.SetValue(event.DurationMs)
	case "claude_code.latency_ms":
		req.SetValue(event.LatencyMs)
	case "claude_code.tool_count":
		req.SetValue(event.ToolCount)
	case "claude_code.failure_count":
		req.SetValue(event.FailureCount)
	case "claude_code.dropped":
		req.SetValue(event.Dropped)
	case "claude_code.raw_excerpt":
		req.SetValue(event.RawExcerpt)

	default:
		return fmt.Errorf("unknown field: %s", req.Field())
	}

	return nil
}

// --- 7. NextBatch() - Event Batch Delivery ---
func (inst *ClaudeCodeInstance) NextBatch(pState sdk.PluginState, evts sdk.EventWriters) (int, error) {
	n := 0
	timeout := time.After(30 * time.Millisecond)

	for n < evts.Len() {
		select {
		case event, ok := <-inst.eventCh:
			if !ok {
				if n == 0 {
					return 0, sdk.ErrEOF
				}
				return n, nil
			}

			writer := evts.Get(n)
			encoder := gob.NewEncoder(writer.Writer())
			if err := encoder.Encode(event); err != nil {
				debugLog("GOB encode error: %v (event: %+v)", err, event)
				continue
			}
			writer.SetTimestamp(uint64(event.Timestamp.UnixNano()))
			n++

		case <-timeout:
			if n == 0 {
				return 0, sdk.ErrTimeout
			}
			return n, nil
		}
	}

	return n, nil
}

// --- Close() - Resource Cleanup ---
// FP-010: watcher, fd, goroutine, channel must be released.
// P006/P011/P015: ordered shutdown to avoid send-on-closed-channel panics
// and goroutine leaks:
//
//  1. cancel ctx → readLoop / pollLoop start to exit
//  2. close fsnotify watcher (Events/Errors channels close as a side effect)
//  3. set closed=true atomic flag (gate for any in-flight deliver())
//  4. wg.Wait() for both goroutines to actually return
//  5. close fds
//  6. close eventCh (no more producers exist at this point)
func (inst *ClaudeCodeInstance) Close() {
	inst.closeOnce.Do(func() {
		if inst.cancel != nil {
			inst.cancel()
		}
		if inst.watcher != nil {
			inst.watcher.Close()
		}
		inst.closed.Store(true)
		inst.wg.Wait()

		inst.mu.Lock()
		for _, f := range inst.files {
			if f.file != nil {
				f.file.Close()
			}
		}
		inst.files = nil
		inst.mu.Unlock()

		close(inst.eventCh)

		debugLog("Instance closed. Dropped=%d Rotations=%d Reopens=%d",
			atomic.LoadUint64(&inst.droppedEvents),
			atomic.LoadUint64(&inst.rotationEvents),
			atomic.LoadUint64(&inst.reopenEvents))
	})
}

